/**
 * Maharashtra district geometry for the interactive GIS map.
 * Source: public district boundaries (2011 Census / Survey of India based GeoJSON,
 * github.com/udit-001/india-maps-data), projected to a flat SVG space and simplified.
 * Names use current official spellings (e.g. Ahilyanagar, Dharashiv, Chhatrapati Sambhajinagar);
 * boundaries are the 2011 geometry.
 * Generated file — do not edit by hand.
 */
export interface DistrictShape {
  id: string;
  en: string;
  mr: string;
  d: string;
  cx: number;
  cy: number;
}

export const MAP_BOUNDS = { minLon: 72.654608, maxLat: 22.033719, cosLat: 0.946537, scale: 128.155596, width: 1000, height: 824 } as const;

/** Project longitude/latitude to the SVG coordinate space of DISTRICTS. */
export function projectLonLat(lon: number, lat: number): { x: number; y: number } {
  return {
    x: (lon - MAP_BOUNDS.minLon) * MAP_BOUNDS.cosLat * MAP_BOUNDS.scale,
    y: (MAP_BOUNDS.maxLat - lat) * MAP_BOUNDS.scale,
  };
}

